declare const __LOOM_ANALYTICS_VERSION__: string;
declare const __LOOM_FLAGS_VERSION__: string;
declare const __LOOM_PLACEHOLDER_VERSION__: string;
declare const __CREATE_LOOM_VERSION__: string;
